"use strict";(globalThis.webpackChunkgrc||=[]).push([[12014],{77739(e){e.exports=JSON.parse('{"citeKey":"fang2009coreaware","slug":"fang-2009-core-aware-0364","title":"Core-Aware Memory Access Scheduling Schemes","authors":["Z. Fang","X.-H. Sun","Y. Chen","S. Byna"],"venue":"The IEEE International Parallel & Distributed Processing Symposium (IPDPS\'09), Rome, Italy","type":"Conference","entryType":"inproceedings","date":"May, 2009","year":2009,"era":"iit","month":5,"doi":"10.1109/ipdps.2009.5161013","abstract":"Multi-core processors have changed the conventional hardware structure and require a rethinking of system scheduling and resource management to utilize them efficiently. However, current multi-core systems are still using conventional single-core memory scheduling. In this study, we investigate and evaluate traditional memory access scheduling techniques, and propose a core-aware memory scheduling for multi-core environments. Since memory requests from the same source exhibit better locality, it is reasonable to schedule the requests by taking the source of the requests into consideration. Motivated from this principle of locality, we propose two core-aware policies based on traditional bank-first and row-first schemes. Simulation results show that the core-aware policies can effectively improve the performance. Compared with the bank-first and row-first policies, the proposed core-aware policies reduce the execution time of certain NAS Parallel Benchmarks by up to 20% in running the benchmarks separately, and by 11% in running them concurrently.","hasAbstract":true,"lede":"Motivated from this principle of locality, we propose two core-aware policies based on traditional bank-first and row-first schemes.","links":{"pdf":"https://grc.iit.edu/papers/2009/fang-2009-core-aware-0364.pdf","slides":"https://grc.iit.edu/papers/2009/fang-2009-core-aware-0364-slides.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["multicore-scheduling"],"memberAuthors":["sun-xian-he","byna-surendra"]}')}}]);